const input = $input.first().json;
let body = (input && input.body !== undefined) ? input.body : input;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
const job_id = ((body || {}).job_id || '').toString().trim();
if (!/^[0-9a-f-]{36}$/i.test(job_id)) throw new Error('job_id (uuid) is required');
return [{ json: { job_id } }];

// Size table — keep in sync with SIZES in dashboard/src/lib/imageGen.ts.
const SIZES = {
  post:     { label: 'Square post',     aspect: '1:1',  w: 1080, h: 1080 },
  portrait: { label: 'Portrait post',   aspect: '4:5',  w: 1080, h: 1350 },
  story:    { label: 'Story / Reel',    aspect: '9:16', w: 1080, h: 1920 },
  banner:   { label: 'Banner',          aspect: '16:9', w: 1200, h: 628 },
};

const flatten = items => items.flatMap(i => Array.isArray(i.json) ? i.json : [i.json]);
const job = flatten($('Fetch Job').all())[0];
if (!job || !job.id) throw new Error('Job not found');
const refs = flatten($('Fetch References').all()).filter(r => r && r.image_b64);

const gens = (job.image_gen_generations || []).filter(g => g.render_status === 'rendering');
if (!gens.length) throw new Error('No generations waiting to render for job ' + job.id);

const refParts = refs.map(r => ({ inlineData: { mimeType: r.mime_type || 'image/png', data: r.image_b64 } }));

return gens.map(g => {
  const s = SIZES[g.size] || SIZES.post;
  const text = job.prompt_drafted +
    '\n\nFormat: ' + s.label + ', ' + s.aspect + ' aspect ratio (final crop ' + s.w + 'x' + s.h + 'px). Fill the whole frame; keep key subjects and any text away from the edges.' +
    (refParts.length
      ? '\n\nThe attached images are this brand\'s reference images. Match their visual style — palette, lighting, rendering style, typography treatment and mood — but create a new image; do not copy them.'
      : '');
  return {
    json: {
      job_id: job.id,
      generation_id: g.id,
      size: g.size,
      gemini_body: {
        contents: [{ parts: [{ text }, ...refParts] }],
        generationConfig: { responseModalities: ['IMAGE', 'TEXT'], imageConfig: { aspectRatio: s.aspect } },
      },
    },
  };
});

const MODEL = 'gemini-2.5-flash-image';
const reqs = $('Build Requests').all();
return $input.all().map((item, i) => {
  const req = reqs[i] ? reqs[i].json : {};
  const res = item.json || {};
  let image_b64 = '';
  let mime_type = 'image/png';
  const parts = (res.candidates && res.candidates[0] && res.candidates[0].content && res.candidates[0].content.parts) || [];
  for (const part of parts) {
    if (part.inlineData && part.inlineData.data) { image_b64 = part.inlineData.data; mime_type = part.inlineData.mimeType || 'image/png'; break; }
  }
  let patch;
  if (image_b64) {
    patch = { render_status: 'done', image_b64, mime_type, generated_by: MODEL, error: null };
  } else {
    let reason = '';
    if (res.error) reason = typeof res.error === 'string' ? res.error : (res.error.message || JSON.stringify(res.error));
    else if (res.promptFeedback && res.promptFeedback.blockReason) reason = 'Blocked: ' + res.promptFeedback.blockReason;
    else if (res.candidates && res.candidates[0] && res.candidates[0].finishReason) reason = 'No image returned (finishReason ' + res.candidates[0].finishReason + ')';
    else reason = 'Gemini returned no image — check the Gemini credential, billing, and model availability';
    patch = { render_status: 'failed', error: reason.slice(0, 1000), generated_by: MODEL };
  }
  return { json: { job_id: req.job_id, generation_id: req.generation_id, patch } };
});

const results = $('Extract Image').all().map(i => i.json);
const done = results.filter(r => r.patch.render_status === 'done').length;
const failed = results.length - done;
const job_id = results.length ? results[0].job_id : $('Parse Input').first().json.job_id;
return [{ json: { job_id, patch: done > 0
  ? { status: 'done', error: failed ? (failed + ' of ' + results.length + ' sizes failed') : null }
  : { status: 'failed', error: 'All sizes failed: ' + (results[0] ? results[0].patch.error : 'unknown') } } }];
